   371	static void addDefaultPort(struct ndpi_detection_module_struct *ndpi_str,
   372	                           ndpi_port_range *range,
   373	                           ndpi_proto_defaults_t *def,
   374	                           u_int8_t customUserProto,
   375	                           ndpi_default_ports_tree_node_t **root,
   376	                           const char *_func, int _line) {
   377	  u_int16_t port;
   378	
   379	  for(port=range->port_low; port<=range->port_high; port++) {
   380	    ndpi_default_ports_tree_node_t *node = (ndpi_default_ports_tree_node_t*)ndpi_malloc(sizeof(ndpi_default_ports_tree_node_t));
   381	    ndpi_default_ports_tree_node_t *ret;
   382	
   383	    if(!node) {
   384	      NDPI_LOG_ERR(ndpi_str, "%s:%d not enough memory\n", _func, _line);
   385	      break;
   386	    }
   387	
   388	    node->proto = def, node->default_port = port, node->customUserProto = customUserProto;
   389	    ret = (ndpi_default_ports_tree_node_t*)ndpi_tsearch(node, (void*)root, ndpi_default_ports_tree_node_t_cmp); /* Add it to the tree */
   390	
   391	    if(ret != node) {
   392	      NDPI_LOG_DBG(ndpi_str, "[NDPI] %s:%d found duplicate for port %u: overwriting it with new value\n",
   393	                   _func, _line, port);
   394	
   395	      ret->proto = def;
   396	      ndpi_free(node);
   397	    }
   398	  }
   399	}
